// Verus specification for the "boring apartment number" problem.
// We declare a number x to be "boring" if it is a repdigit ddd…d
// with 1 ≤ d ≤ 9 and 1 ≤ k ≤ 4 digits.  We then show that the
// score of x is exactly (d−1)*10 + k*(k+1)/2.

#![allow(unused)]  
verus! {

    // repdigit(d,k) = the integer consisting of k copies of digit d.
    //    repdigit(d,1) = d
    //    repdigit(d,k) = repdigit(d,k-1)*10 + d   (for k>1)
    #[verifier(spec)]
    fn repdigit(d: i32, k: i32) -> i32
        requires 1 <= d && d <= 9
        requires 1 <= k && k <= 4
        ensures  1 <= result && result <= 9999
        decreases k
    {
        if k == 1 {
            d
        } else {
            repdigit(d, k - 1) * 10 + d
        }
    }

    // x is a boring apartment number iff there exist d,k with
    // x == repdigit(d,k), 1≤d≤9, 1≤k≤4
    #[verifier(spec)]
    fn is_boring(x: i32) -> bool {
        1 <= x && x <= 9999 &&
        exists |d: i32, k: i32| 1 <= d && d <= 9 && 1 <= k && k <= 4 && repdigit(d, k) == x
    }

    // Given a boring x, extract its repeated digit d.
    #[verifier(spec)]
    fn boring_digit(x: i32) -> i32
        requires is_boring(x)
        ensures  1 <= result && result <= 9
        // there is some k with which this digit recreates x
        ensures  exists |k: i32| 1 <= k && k <= 4 && repdigit(result, k) == x
    {
        choose |d: i32| {
            1 <= d && d <= 9 &&
            exists |k: i32| 1 <= k && k <= 4 && repdigit(d, k) == x
        }
    }

    // Given a boring x, extract its length k.
    #[verifier(spec)]
    fn boring_length(x: i32) -> i32
        requires is_boring(x)
        ensures  1 <= result && result <= 4
        ensures  repdigit(boring_digit(x), result) == x
    {
        choose |k: i32| {
            1 <= k && k <= 4 &&
            repdigit(boring_digit(x), k) == x
        }
    }

    // The main specification for solve:
    //   If x is boring (a single digit d repeated k times),
    //   then its score is:
    //     (d−1)*10  +  (1 + 2 + … + k)
    //               = (d−1)*10  +  k*(k+1)/2
    #[verifier(spec)]
    fn solve(x: i32) -> i32
        requires is_boring(x)
        ensures  result ==
                 (boring_digit(x) - 1) * 10
                 + (boring_length(x) * (boring_length(x) + 1) / 2)
    {
        // no executable body is needed for a spec
        result
    }

}